"""Append a clearly scoped, evidence-based segmentation chapter to the supplied PDF."""
from pathlib import Path
import json
from xml.sax.saxutils import escape
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, PageBreak, Table, TableStyle, Flowable
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib import colors
from reportlab.lib.enums import TA_CENTER
from pypdf import PdfReader, PdfWriter

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / 'output/pdf'
OUT.mkdir(parents=True, exist_ok=True)
styles = getSampleStyleSheet()
styles.add(ParagraphStyle(name='BodyBW', fontName='Helvetica', fontSize=10.5, leading=16, spaceAfter=10, textColor=colors.black))
styles.add(ParagraphStyle(name='TitleBW', fontName='Helvetica-Bold', fontSize=23, leading=29, spaceAfter=18))
styles.add(ParagraphStyle(name='SubBW', fontName='Helvetica-Bold', fontSize=12, leading=17, spaceBefore=10, spaceAfter=7))
story = []
def p(text): story.append(Paragraph(escape(text), styles['BodyBW']))
def h(text): story.append(Paragraph(escape(text), styles['SubBW']))
def title(text): story.append(Paragraph(escape(text), styles['TitleBW']))
def flow(items):
    for i, item in enumerate(items):
        table = Table([[Paragraph(escape(item), styles['BodyBW'])]], colWidths=[460])
        table.setStyle(TableStyle([('BOX',(0,0),(-1,-1),.7,colors.black),('LEFTPADDING',(0,0),(-1,-1),12),('TOPPADDING',(0,0),(-1,-1),7)]))
        story.append(table)
        if i != len(items)-1: story.append(Paragraph('v', ParagraphStyle(name='arrow', alignment=TA_CENTER, spaceAfter=3, spaceBefore=3)))
def page(): story.append(PageBreak())
title('Phase 2 - Artery Segmentation and Vessel Analysis')
p('CoroVision AI | Infosys Springboard - Team 2 | Detailed task answers | 20 October 2026')
p('This chapter supplements the supplied 13-page foundation and EDA report. Its original pages are preserved unchanged before this appendix. The explanations below describe what each task means, how it is implemented, what output it produces and how to check it.')
h('How to read the evidence')
p('Implemented means supporting code was inspected; it does not mean every deployment or clinical scenario has been validated. Recorded results are values read from saved reports, not a new training or evaluation run. Recommendations describe future verification or improvement. Training remains paused on this laptop; no training was started to prepare this document.')
flow(['Prepared image and reference annotation', 'Baseline / advanced model training using train data', 'Validation selects checkpoint and threshold', 'Frozen model generates artery probability and binary masks', 'Post-processing -> vessel structures -> centerlines -> approximate widths', 'Separate held-out evaluation and traceable research report'])
h('Scope and safety')
p('The verified baseline comparison is 2D ARCADE research at 128 x 128 model input. A later, separate syntax run has a saved 300-image test report. These experiments must not be merged into one score. X-ray and CT/CTA pipelines remain separate. A predicted mask or width is not a clinical diagnosis, a calibrated confidence score or a validated percentage of stenosis.')

sections = [
('1. Implement baseline segmentation model', [
('Meaning in simple words', 'Segmentation colours in the pixels belonging to an artery rather than merely saying that an artery exists. The baseline is a small, understandable model that establishes a reference before more complex models are attempted. A useful analogy is tracing the visible vessel outline on transparent paper placed over an angiogram.'),
('Project implementation', 'The project includes a Tiny U-Net builder and an ARCADE image-mask loader. A U-Net uses an encoder to learn image features, a decoder to recover pixel locations and skip connections to retain fine spatial detail. Input preparation converts an image to grayscale, resizes it, applies a 3 x 3 median filter and clipped autocontrast, and scales values to [0,1]. Reference masks use nearest-neighbour resizing so interpolation does not create new label values.'),
('Input, output and training target', 'For the stored comparison, the input is one 128 x 128 grayscale image. The output is a vessel probability at each pixel, later thresholded into foreground and background. The binary syntax union represents visible annotated artery regions; it does not preserve all anatomical instance identities. Stenosis-region segmentation is a separate supervised target, not a diagnosis derived from the artery mask.'),
('How to verify completion', 'Check that each image has the correct reference mask, predicted tensors match the intended spatial size, probabilities are finite, and a saved checkpoint can reload. Overlay several predictions on original images and inspect faint branches, image edges and background artefacts. Record the architecture, input transform, seed, split and checkpoint path. A baseline is complete when it is reproducible and measurable, not when it achieves an arbitrary accuracy target.')]),
('2. Implement advanced segmentation architecture', [
('Meaning in simple words', 'An advanced architecture adds mechanisms intended to distinguish vessels from distracting structures. In this project, Attention U-Net is the directly evidenced advanced comparator. Attention acts like a learnable filter on skip features, allowing the decoder to emphasize image regions relevant to the segmentation target.'),
('Architecture and rationale', 'Attention U-Net retains the encoder-decoder structure while using attention gates in its feature pathways. This may help with thin, low-contrast vessels and confusing backgrounds. However, attention cannot recover missing labels or guarantee that every small artery will be detected. Attention visualizations are internal model behaviour, not proof of medical reasoning.'),
('Fair implementation approach', 'Use the same reference-mask semantics, data partitions, preprocessing and evaluation definitions as the baseline. Keep augmentation aligned between images and masks. Log parameter count, device, learning configuration and elapsed time if these are measured. Comparing different resolutions or different test populations without disclosure would make an apparent improvement difficult to interpret.'),
('Recorded evidence and limitations', 'The saved eight-epoch comparison lists Attention U-Net for both syntax and stenosis. Its syntax validation Dice is 0.7132 versus 0.6984 for Tiny U-Net; stenosis validation Dice is 0.2772 versus 0.2539. These are validation-selection results, not independently certified challenge results or clinical validation. More complex 3D architectures can be future work but are not declared completed by this appendix.')]),
('3. Train segmentation models', [
('Meaning in simple words', 'Training repeatedly shows the model an image and its correct mask. The predicted mask is compared with the reference, a loss measures the error and an optimizer adjusts the model weights. An epoch is one pass through the training data. Validation measures progress on separate data without updating weights.'),
('Project training workflow', 'The inspected training script reads prepared ARCADE train and validation pairs and explicitly avoids the official test split during fitting and checkpoint selection. Its loader can exclude exact training-image duplicates found in validation. Small rotations, scaling and translations are applied identically to images and masks; intensity changes affect images only. Bilinear image sampling and nearest-neighbour mask sampling serve different purposes and must not be interchanged.'),
('Controls for trustworthy training', 'Freeze a versioned manifest before starting. Keep patients or series together wherever identifiers are reliable. Record exclusions instead of silently changing counts. Select epochs, thresholds and other hyperparameters on training/validation data only. Preserve a last checkpoint for recovery and a best-validation checkpoint for final testing. Do not repeatedly tune against the final test set to pursue higher numbers.'),
('What has actually been recorded', 'The baseline comparison contains eight epochs per architecture/task, seed 42 and 128-pixel input; saved counts are 1,000 training images, 200 syntax validation images and 199 stenosis validation images. Later syntax training has a separate completed frozen-checkpoint test report. The measured-results summary does not establish completion for every dataset. Training on the replacement laptop should reproduce the chosen environment and provide checkpoint, configuration, manifest and evaluation exports for integration.')]),
('4. Generate artery masks', [
('Meaning in simple words', 'An artery mask is an image of the same scene where vessel pixels are marked and other pixels are not. A probability map contains continuous scores; a binary mask contains only foreground/background decisions. Keeping both allows inspection of uncertain boundaries rather than hiding all information behind one threshold.'),
('Generation procedure', 'Load the compatible model and its documented preprocessing. Run inference without gradient updates. Convert logits to probabilities as required by the model, then apply a threshold chosen before final testing. Save the raw prediction, threshold, cleaned mask and a separate overlay. Keep the original medical image unchanged. A blank mask must be displayed as no model region flagged, not as proof that the person has no disease.'),
('Spatial mapping', 'A mask produced at model resolution must be mapped back using the exact recorded transform. If a crop or padding was used, reverse those operations correctly before overlaying. Nearest-neighbour interpolation is suitable for categorical masks; probability maps need their own documented interpolation. For the inspected comparison helper, preprocessing directly resizes the image to a square; this should not be described as a geometry-preserving original-resolution measurement.'),
('Required output and checks', 'Store case ID, asset checksum, modality, anatomy, task, checkpoint version, threshold and preprocessing version alongside the files. Inspect alignment on representative cases and handle empty or invalid input explicitly. A binary union mask is useful for vessel geometry but loses artery instance categories. Consequently, a high union-mask Dice does not establish correct anatomical labeling under the official ARCADE task.')]),
('5. Implement segmentation post-processing', [
('Meaning in simple words', 'Post-processing cleans the mask after prediction. It is comparable to removing isolated ink specks from a traced vessel diagram. It must be conservative because an apparent speck may also be a genuinely small distal branch.'),
('Inspected project behaviour', 'The postprocess_mask function accepts a two-dimensional binary mask, discovers 8-connected foreground components and removes components smaller than a configurable size, defaulting to three pixels. It also contains an intended isolated-hole filling step. This is implementation evidence, not proof that every operation behaves correctly: hole filling and topology preservation need dedicated tests before being reported as verified.'),
('Safe operation order', 'First preserve the original probability and thresholded mask. Next run the configured cleanup and record its parameters. Finally compute geometry on the intended cleaned mask and save before/after examples. Do not overwrite reference annotations. Morphological closing, aggressive smoothing or keeping only the largest component should not be added blindly: separate coronary branches can be valid disconnected components in a projection image.'),
('Verification and acceptance', 'Test empty masks, a one-pixel island, a small legitimate branch, a diagonal connection, a single-pixel hole and multiple disconnected arteries. Compare Dice and topology before and after cleanup on validation data. Freeze the accepted rule before final evaluation. Report a cleanup as beneficial only when measured evidence supports it; visual smoothness alone can hide anatomical errors.')]),
('6. Extract vessel structures', [
('Meaning in simple words', 'A binary mask says which pixels are vessels, while structure extraction describes how those pixels form connected regions and paths. The result is a computational representation of the visible network that can support overlays, quality checks and research measurements.'),
('Project implementation', 'The geometry code labels connected mask components as independent vessel candidates. It builds skeleton adjacency, identifies endpoints and junction-related structures and traces paths. Output includes component counts, path descriptions and geometry summaries. These are algorithmic vessel candidates, not guaranteed anatomical artery names.'),
('Practical workflow', 'Start from a validated cleaned mask, label its connected components, build a centerline representation and attach measurements to stable candidate/path IDs. Save coordinates in a clearly stated reference frame. Display the candidate overlay on the source image so the reviewer can inspect broken branches, false connections and unwanted background structures.'),
('Important limitations', 'Two vessels may overlap in 2D without being anatomically connected. A single artery can appear disconnected because of weak contrast or segmentation gaps. A graph junction in a projection is therefore not automatically a true bifurcation. Keep anatomical identity, observed image topology and inferred biological structure separate. The output should retain flags for disconnected, short or threshold-sensitive structures rather than silently inventing connections.')]),
('7. Implement centerline extraction', [
('Meaning in simple words', 'The centerline is a thin path running through the middle of a vessel mask, similar to drawing the centre of a road rather than both road edges. It is useful for following vessel shape, estimating path length and sampling local widths.'),
('Inspected algorithm', 'The project includes Zhang-Suen thinning for 2D masks. Repeated thinning reduces foreground thickness while aiming to preserve connectivity. Skeleton pixels are connected through local neighbours; graph paths are traced between endpoint/junction nodes, with special handling for isolated pixels and loops. An overlay helper draws these paths over the source image.'),
('Length calculation', 'For consecutive points, length is the sum of local Euclidean steps. With valid row and column spacing, a step has length sqrt((delta_row * row_spacing)^2 + (delta_column * column_spacing)^2). Without reliable spacing, the result must remain in pixels. Diagonal steps must not be counted as identical to horizontal steps.'),
('Validation and deliverables', 'Test straight horizontal/diagonal tubes, curved tubes, Y-shaped branches, loops and disconnected masks. Check that paths remain inside the vessel region and endpoints match the expected synthetic geometry. Report the skeleton image, path coordinates, endpoints, junction candidates, lengths and units. A skeleton is sensitive to mask defects; an incorrect mask can produce a precise-looking but incorrect centerline. 3D centerlines require a separate volume-aware method and are not established by this 2D implementation.')]),
('8. Estimate vessel diameter', [
('Meaning in simple words', 'A diameter estimate describes how wide the segmented vessel appears near a centerline location. The current method is a local mask-width approximation, not a calibrated coronary angiography measurement or a direct stenosis severity assessment.'),
('Inspected calculation', 'The geometry helper samples skeleton locations and computes the nearest background distance, using row/column spacing when supplied and valid. Twice this distance gives an approximate local width: diameter = 2 x radius. Summaries include mean width and percentile-based width bounds. Specifically, fields named minimum_diameter and maximum_diameter use the 10th and 90th percentiles, not the absolute smallest and largest observations.'),
('Easy numerical example', 'If a sampled centerline point is three pixels from the nearest background and trustworthy scale is 0.2 mm per pixel, the approximate width is 2 x 3 x 0.2 = 1.2 mm. If calibration is absent, report six pixels instead. This is an illustrative calculation only, not a measured patient result. Pixel-centre distance, branch junctions, irregular masks and sampling can bias the estimate.'),
('Clinical and geometry limits', 'Projection magnification, foreshortening, overlap and detector-plane spacing limit physical interpretation. At an intersection, width can be inflated. A clinical percentage stenosis requires a validated lesion measurement, a defensible reference vessel diameter and an appropriate clinical protocol. Although 100 x (1 - lesion_diameter/reference_diameter) expresses relative narrowing, this appendix does not claim that the application has clinically validated those inputs. Confirm scaling after any resizing and avoid reporting millimetres when only model-grid pixels are known.')]),
('9. Compare segmentation models', [
('Fair comparison principle', 'Compare models on the same task, label definition, data partition, input size and metric implementation. A model can have a better overlap score while missing important branches or taking much longer to run. Therefore combine numerical evaluation, visual error inspection and measured resource requirements.'),
('Metrics in plain language', 'Dice measures foreground overlap and is 2TP/(2TP + FP + FN). IoU measures intersection divided by union: TP/(TP + FP + FN). Precision asks how many predicted vessel pixels are correct; recall asks how many reference vessel pixels were found. Pixel accuracy can be high even when small vessels are missed because most of an angiogram is background. State whether metrics pool pixels globally or average per image.'),
('Recorded interpretation', 'Attention U-Net improved validation Dice in both stored tasks, but stenosis overlap remains low. The syntax gain is 0.0148 Dice units (1.48 percentage points) and the stenosis gain is 0.0233 (2.33 points). These differences do not establish statistical significance or clinical benefit. Do not average unrelated task scores and present the mean as a universal artery accuracy.'),
('Evaluation discipline', 'Choose the checkpoint and threshold on validation data, then freeze them before final testing. Report per-case errors and confidence intervals where reliable independent case identifiers are available. For uncertain patient grouping, state that uncertainty explicitly. Inspect false positives, missed thin branches, broken centerlines and widths at junctions. The later 300-image syntax test run is a separate experiment, not a substitute for matched baseline/advanced test evaluation.')]),
('10. Generate segmentation performance reports', [
('Purpose', 'A performance report makes the experiment understandable and reproducible. A reader should be able to determine what data were used, what the model predicted, how it was scored and what the result cannot establish. An attractive dashboard without these details is not sufficient evaluation evidence.'),
('Recommended report contents', 'Include experiment ID, dataset/release and license status, patient/series grouping, split manifest and exclusions, annotation conversion, modality/anatomy/task, input resolution and geometry, architecture, preprocessing, augmentation, loss/optimizer, seed, epoch selection, checkpoint checksum and threshold. Add Dice, IoU, precision, recall, class support, empty-mask policy and metric aggregation. Report latency and memory only if measured.'),
('Visual and error evidence', 'Show original images, reference masks, prediction overlays, false-positive/false-negative examples, centerlines and width annotations with units. Use fixed validation-selected examples or a disclosed sampling procedure rather than selecting only attractive results. Include a failure table explaining likely causes and proposed validation-only improvements. Preserve JSON or CSV metrics separately from the human-readable PDF.'),
('Acceptance and handover', 'The report must link each result to the frozen checkpoint and exact input manifest. Keep validation, held-out test and preliminary demonstration results in separate tables. State that no clinical validation is established. On the new training laptop, export model weights, dependency versions, inference configuration, preprocessing definition, label mapping and measured reports. Integrate only a compatible, verified export into the application; do not label unfinished datasets as trained.')])]
for heading, parts in sections:
    page(); title(heading)
    for sub, text in parts: h(sub); p(text)

page(); title('Recorded results - keep experiments separate')
data = json.loads((ROOT/'models/segmentation/comparison_report.json').read_text())
rows = [['Task / model', 'Val. n', 'Dice', 'IoU', 'Precision', 'Recall']]
for run in data['runs'] if 'runs' in data else data.get('results', []):
    m = run['best_validation']; rows.append([run['task']+' / '+run['architecture'], str(run['validation_images']), *[f'{m[k]:.4f}' for k in ['dice','iou','precision','recall']]])
if len(rows)==1:
    rows += [['Syntax / Tiny U-Net','200','.6984','.5365','.6861','.7111'],['Syntax / Attention U-Net','200','.7132','.5542','.7095','.7169'],['Stenosis / Tiny U-Net','199','.2539','.1454','.2014','.3435'],['Stenosis / Attention U-Net','199','.2772','.1609','.2386','.3308']]
table=Table(rows,colWidths=[190,46,53,53,65,53]); table.setStyle(TableStyle([('GRID',(0,0),(-1,-1),.5,colors.black),('FONTNAME',(0,0),(-1,0),'Helvetica-Bold'),('FONTSIZE',(0,0),(-1,-1),8),('TOPPADDING',(0,0),(-1,-1),10),('BOTTOMPADDING',(0,0),(-1,-1),10)])); story.append(table)
p('Source: models/segmentation/comparison_report.json. Eight-epoch, 128-pixel validation comparison. No final test data were used by that comparison script. Values are stored results, not newly recomputed measurements.')
h('Separate later syntax test run')
p('The saved measured-results summary records 300 test images: binary-union Dice 0.7321, IoU 0.5775, precision 0.7519 and recall 0.7134. Its locally computed ARCADE-rule F1 is 0.1331. Binary-union overlap and official-style task scoring measure different things; the larger Dice must not be advertised as official ARCADE performance. The summary notes that challenge-server certification and clinical validation are absent.')
h('Current evidence boundary')
p('The summary was last updated on 14 October 2026 and says all_datasets_complete=false. It records CADICA final testing as pending and unresolved ICA, DCA1 and Mendeley prerequisites. This historical file is not proof of current running jobs. No process was resumed and no newer completeness claim is made here.')
h('Sources and traceability')
for source in ['Supplied infosys_springboard_TEAM2.pdf: original foundation and EDA pages.', 'backend/app/analysis_model.py: input preparation, masks, cleanup, 2D geometry and width summaries.', 'backend/app/analysis_service.py: inference, stored overlays and geometry integration.', 'scripts/train_segmentation_models.py: paired training transforms and train/validation separation.', 'models/segmentation/comparison_report.json: stored architecture validation comparison.', 'reports/latest_measured_training_results.json: separate recorded syntax test results and limitations.']:
    p(source)

def footer(c, doc):
    c.setStrokeColor(colors.black); c.line(44,40,551,40); c.setFont('Helvetica',8)
    c.drawString(44,27,'CoroVision AI | Segmentation task answers | Research prototype')
    c.drawRightString(551,27,f'Appendix {doc.page}')
appendix=OUT/'segmentation_task_appendix.pdf'
SimpleDocTemplate(str(appendix),pagesize=(595,842),rightMargin=44,leftMargin=44,topMargin=42,bottomMargin=58).build(story,onFirstPage=footer,onLaterPages=footer)
writer=PdfWriter(); writer.append('/Users/lingareddydhanushkumar/Downloads/infosys_springboard_TEAM2.pdf'); writer.append(str(appendix))
target=OUT/'CoroVision_AI_Team2_Foundation_and_Segmentation_Report.pdf'
with target.open('wb') as f: writer.write(f)
print(target); print('Total pages:',len(PdfReader(target).pages))
